import{_ as s,o as t,c as n,a4 as i}from"./chunks/framework.BE47AOxC.js";const g=JSON.parse('{"title":"3. Extensions (plugins)","description":"Extrait de docs/notice-utilisateur.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"3. Extensions (plugins)","description":"Extrait de docs/notice-utilisateur.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"documentation/notice/3-extensions-plugins.md","filePath":"documentation/notice/3-extensions-plugins.md"}'),a={name:"documentation/notice/3-extensions-plugins.md"};function r(o,e,l,u,c,d){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="3-extensions-plugins" tabindex="-1">3. Extensions (plugins) <a class="header-anchor" href="#3-extensions-plugins" aria-label="Permalink to &quot;3. Extensions (plugins) {#3-extensions-plugins}&quot;">​</a></h1><p>Certaines fonctionnalités ne font pas partie du socle et s&#39;ajoutent (ou se retirent) par organisation, sans jamais toucher au reste des contenus déjà créés. <strong>Vingt-neuf extensions</strong> sont livrées avec le CMS, réparties en cinq <strong>packs</strong> selon le métier auquel elles s&#39;adressent. Un pack n&#39;est qu&#39;une façon de lire le catalogue : les extensions s&#39;installent et se désinstallent une par une, et rien n&#39;empêche d&#39;en mélanger de plusieurs packs.</p><p><strong>Plusieurs extensions servent à tout le monde</strong>, malgré un nom né du secteur public. Une agence utilisera <em>Albums</em> comme portfolio, <em>Paroles d&#39;acteurs</em> comme mur de témoignages clients et <em>Annuaire de personnes</em> comme page équipe ; une rédaction utilisera <em>Actualités</em> pour ses articles et <em>Publications</em> pour ses hors-séries. Les packs métier ci-dessous ne les redoublent pas : ils s&#39;y rattachent, et chacun indique lesquels installer à côté de lui.</p><h2 id="pack-secteur-public-français" tabindex="-1">Pack secteur public français <a class="header-anchor" href="#pack-secteur-public-français" aria-label="Permalink to &quot;Pack secteur public français {#pack-secteur-public-français}&quot;">​</a></h2><h3 id="démarches-en-ligne-et-candidatures" tabindex="-1">Démarches en ligne et candidatures <a class="header-anchor" href="#démarches-en-ligne-et-candidatures" aria-label="Permalink to &quot;Démarches en ligne et candidatures {#démarches-en-ligne-et-candidatures}&quot;">​</a></h3><ul><li><strong>SVE — Saisine par voie électronique</strong> : le circuit complet d&#39;une démarche en ligne côté back-office (tableau de bord des dossiers, export, échange de messages avec l&#39;usager).</li><li><strong>FAQ</strong> : une foire aux questions, avec un formulaire public de dépôt d&#39;une question — la question devient une fiche que l&#39;équipe complète d&#39;une réponse avant de la publier.</li><li><strong>Actualités</strong> : le fil d&#39;actualités du site, avec un formulaire public « Proposer une actualité » et une localisation facultative, choisie dans l&#39;annuaire des lieux ou saisie librement.</li><li><strong>Agenda</strong> : le calendrier d&#39;événements du site, avec formulaire public de proposition, ajout au calendrier personnel du visiteur, et dépublication automatique une fois l&#39;événement passé.</li><li><strong>Offres d&#39;emploi</strong> : les offres d&#39;emploi de la collectivité, avec deux formulaires publics de candidature — l&#39;un pour postuler à une offre précise, l&#39;autre en candidature spontanée — chacun notifiant automatiquement la bonne personne côté recrutement.</li><li><strong>RDV &amp; réservations</strong> : des services réservables (permanences, équipements, salles) et le formulaire public de demande. Les créneaux libres sont calculés à la demande à partir des horaires déclarés et des réservations déjà prises ; l&#39;usager peut annuler avec son numéro de dossier, sans avoir de compte.</li></ul><h3 id="annuaires" tabindex="-1">Annuaires <a class="header-anchor" href="#annuaires" aria-label="Permalink to &quot;Annuaires {#annuaires}&quot;">​</a></h3><ul><li><strong>Glossaire</strong> : un glossaire de termes administratifs, présenté par ordre alphabétique ; tout terme qui y figure devient automatiquement un lien vers sa définition partout ailleurs où il apparaît sur le site.</li><li><strong>Annuaire des lieux</strong> : un répertoire interne de lieux (mairie annexe, gymnase, médiathèque...) pour rattacher précisément une actualité ou un événement à une adresse existante, plutôt que de la ressaisir à chaque fois.</li><li><strong>Annuaire de personnes</strong> : un annuaire de fiches personnelles (élus, agents, contacts d&#39;association) avec attestation obligatoire d&#39;autorisation de publication : une fiche non attestée reste modifiable par son auteur mais n&#39;apparaît plus nulle part sur le site public, y compris dans les listes et les blocs de page.</li><li><strong>Annuaires de structure</strong> : quatre annuaires indépendants — associations, commerces, équipements, services — chacun avec sa propre page et ses propres thématiques, bâtis sur une même fiche (coordonnées, horaires, réseaux sociaux, interlocuteur).</li><li><strong>Annuaire des élu-e-s</strong> : la fiche d&#39;un-e élu-e (mandats et fonctions, permanences, portrait, réseaux sociaux). Elle n&#39;a pas de page liste générée : l&#39;organigramme et les trombinoscopes se composent à la main dans une page, avec les blocs du Page Builder.</li><li><strong>Offre de soins</strong> : sept fiches liées entre elles pour un établissement de santé — bâtiments, unités d&#39;hospitalisation, pôles, services, équipes médicales, médecins, consultations. Seule la fiche du médecin porte des données personnelles, avec son attestation de publication.</li></ul><h3 id="contenus-éditoriaux" tabindex="-1">Contenus éditoriaux <a class="header-anchor" href="#contenus-éditoriaux" aria-label="Permalink to &quot;Contenus éditoriaux {#contenus-éditoriaux}&quot;">​</a></h3><ul><li><strong>Paroles d&#39;acteurs</strong> : un recueil de témoignages (portraits, interviews) présentés en fiches, avec une page liste filtrable.</li><li><strong>Publications</strong> : une bibliothèque de documents à télécharger (rapports, bulletins, délibérations), avec fiche par document, liste filtrable et flux RSS.</li><li><strong>Albums</strong> : des albums mêlant photos et vidéos, présentés en fiches, avec une page liste filtrable.</li><li><strong>Marchés publics</strong> : les avis de marché public en cours, avec date limite de réponse, statut d&#39;attribution et documents à télécharger.</li><li><strong>Flash Info</strong> : un bandeau ou une fenêtre d&#39;alerte affichée en tête de toutes les pages publiques, avec sa propre programmation de début et de fin d&#39;affichage.</li><li><strong>Calendrier des travaux</strong> : les chantiers en cours et à venir, datés, localisés, avec le contact du service qui les suit.</li></ul><h3 id="consultation-du-public" tabindex="-1">Consultation du public <a class="header-anchor" href="#consultation-du-public" aria-label="Permalink to &quot;Consultation du public {#consultation-du-public}&quot;">​</a></h3><ul><li><strong>Sondages</strong> : une question, plusieurs réponses, un vote public et ses résultats. Le blocage d&#39;un second vote depuis le même navigateur est optionnel et ne stocke rien côté serveur.</li><li><strong>Enquêtes et études d&#39;opinion</strong> : des questionnaires à plusieurs questions (échelles d&#39;accord, choix unique ou multiple, texte libre). Les réponses ne sont consultables qu&#39;en back-office.</li></ul><h3 id="mise-en-page" tabindex="-1">Mise en page <a class="header-anchor" href="#mise-en-page" aria-label="Permalink to &quot;Mise en page {#mise-en-page}&quot;">​</a></h3><ul><li><strong>Cartographie</strong> : le bloc « Localiser » pour afficher des contenus sur une carte (réglages de fond de carte, regroupement des points, navigation au clavier).</li><li><strong>Navigation</strong> : les blocs « Menu des sous-pages » et « Page sommaire », qui construisent leur liste depuis l&#39;arbre des pages et respectent les restrictions d&#39;accès.</li><li><strong>Accordéon</strong> : le bloc « cliquer-dérouler », qui peut contenir d&#39;autres blocs.</li><li><strong>Widgets de page d&#39;accueil</strong> : douze blocs prêts à poser sur une page d&#39;accueil — accès rapides, mise en avant, découvrir, actualités et brèves, agenda, albums, publications, mots-clés, annuaires et carte.</li></ul><h3 id="autres-extensions" tabindex="-1">Autres extensions <a class="header-anchor" href="#autres-extensions" aria-label="Permalink to &quot;Autres extensions {#autres-extensions}&quot;">​</a></h3><ul><li><strong>Commentaires</strong> : une extension volontairement minimale, qui ajoute la case « Autoriser les commentaires » au panneau de configuration d&#39;un contenu — elle sert de démonstration du mécanisme d&#39;extension et ne fournit pas encore de stockage ni de modération des commentaires eux-mêmes.</li></ul><h2 id="pack-boutique" tabindex="-1">Pack Boutique <a class="header-anchor" href="#pack-boutique" aria-label="Permalink to &quot;Pack Boutique {#pack-boutique}&quot;">​</a></h2><p>Un <strong>catalogue et une prise de contact commerciale</strong> — ce pack n&#39;est pas une boutique en ligne : il n&#39;y a ni panier, ni paiement, ni gestion de stock, ni commande. À installer à côté : <em>Albums</em> (photos d&#39;ambiance), <em>Paroles d&#39;acteurs</em> (témoignages clients), <em>Cartographie</em> (la carte des points de vente).</p><p>Une seule extension à installer — <strong>Boutique</strong> — qui apporte cinq types de contenu :</p><ul><li><strong>Produit</strong> : la fiche produit — référence, prix, prix barré, marque, catégories, photos, caractéristiques, déclinaisons, documents. Sa page liste se filtre par <strong>plage de prix</strong> et se trie par <strong>prix croissant</strong>.</li><li><strong>Marque</strong> : une fiche de marque ou de fournisseur, utilisée pour rattacher les produits et pour filtrer le catalogue. Elle n&#39;a pas de page liste propre.</li><li><strong>Point de vente</strong> : un magasin, avec son adresse géolocalisée, ses horaires et ses contacts. La page liste cherche « autour de moi » dans un rayon, et les points s&#39;affichent sur une carte avec l&#39;extension Cartographie.</li><li><strong>Demande de devis</strong> : le formulaire public rattaché à un produit. Le prospect reçoit un accusé de réception avec un numéro de dossier, l&#39;alerte part à l&#39;adresse commerciale renseignée <strong>sur le produit concerné</strong>, et le prospect peut retirer sa demande avec son code de suivi.</li><li><strong>Avis client</strong> : un avis noté de 1 à 5, déposé publiquement, qui reste en attente jusqu&#39;à sa relecture par l&#39;équipe.</li></ul><h2 id="pack-rédaction" tabindex="-1">Pack Rédaction <a class="header-anchor" href="#pack-rédaction" aria-label="Permalink to &quot;Pack Rédaction {#pack-rédaction}&quot;">​</a></h2><p>Pour une rédaction, un média, un titre de presse. À installer à côté : <em>Actualités</em> (les articles eux-mêmes), <em>Annuaire de personnes</em> (les signatures et les invités), <em>Publications</em> (hors-séries), <em>Albums</em> (reportages photo).</p><p>Une seule extension à installer — <strong>Rédaction</strong> — qui apporte cinq types de contenu :</p><ul><li><strong>Dossier</strong> : une série éditoriale qui regroupe plusieurs articles autour d&#39;un fil rouge.</li><li><strong>Direct</strong> : le fil en direct d&#39;une soirée électorale ou d&#39;un procès — une suite d&#39;entrées horodatées, dont certaines épinglées en tête. Un direct terminé reste en ligne : c&#39;est l&#39;archive de la soirée.</li><li><strong>Rectificatif</strong> : la correction publiée d&#39;un article — ce qui était écrit, ce qui a été corrigé, à quelle date et pour quel motif (erreur factuelle, attribution, image, droit de réponse). Les rectificatifs se consultent ensemble et ont leur propre flux.</li><li><strong>Tribune</strong> : le formulaire public de dépôt d&#39;une tribune ou d&#39;un droit de réponse, relu et publié par la rédaction.</li><li><strong>Épisode de podcast</strong> : le fichier audio, sa transcription, sa durée et ses invités. C&#39;est le premier contenu livré à brancher la <strong>transcription assistée par IA</strong>, qui propose un texte que quelqu&#39;un relit avant qu&#39;il ne soit appliqué.</li></ul><h2 id="pack-agence" tabindex="-1">Pack Agence <a class="header-anchor" href="#pack-agence" aria-label="Permalink to &quot;Pack Agence {#pack-agence}&quot;">​</a></h2><p>Pour une agence de communication, un studio, un cabinet de conseil. À installer à côté : <em>Paroles d&#39;acteurs</em> (témoignages clients), <em>Annuaire de personnes</em> (l&#39;équipe), <em>Albums</em> (portfolio), <em>Offres d&#39;emploi</em> (recrutement), <em>Agenda</em> (ateliers, portes ouvertes).</p><p>Une seule extension à installer — <strong>Agence</strong> — qui apporte quatre types de contenu :</p><ul><li><strong>Étude de cas</strong> : la fiche de réalisation — le client, le secteur, la problématique, le dispositif, les résultats chiffrés, les visuels, les prestations mobilisées et le témoignage associé.</li><li><strong>Référence client</strong> : le nom, le logo et le secteur d&#39;un client, pour rattacher les études de cas. Pas de page liste propre.</li><li><strong>Prestation</strong> : une offre de service — bénéfices, livrables, tarif indicatif, durée.</li><li><strong>Demande de projet</strong> : le formulaire « parlez-nous de votre projet » — besoin, prestations souhaitées, tranche de budget, échéance, document joint. Le prospect reçoit un numéro de dossier et peut <strong>échanger des messages</strong> avec l&#39;agence sans créer de compte.</li></ul><h2 id="pack-développeurs" tabindex="-1">Pack Développeurs <a class="header-anchor" href="#pack-développeurs" aria-label="Permalink to &quot;Pack Développeurs {#pack-développeurs}&quot;">​</a></h2><p>Pour une équipe produit ou un éditeur de logiciel. Une seule extension à installer — <strong>Développeurs</strong> — qui apporte cinq types de contenu :</p><ul><li><strong>Version</strong> : le journal des versions — numéro, canal (stable, bêta, LTS), notes, liste des changements et ruptures de compatibilité, avec son flux.</li><li><strong>Incident</strong> : la page d&#39;état — composants affectés, gravité, statut, début et fin, mises à jour horodatées et post-mortem. Un incident résolu n&#39;est pas retiré : l&#39;historique est la valeur de la page.</li><li><strong>Référence d&#39;API</strong> : un point d&#39;entrée documenté — méthode, chemin, authentification, paramètres, réponses, exemples, et depuis quelle version il existe.</li><li><strong>Signalement de bug</strong> : le formulaire public de signalement — version concernée, gravité, environnement, étapes de reproduction, pièce jointe. La personne qui signale suit son dossier et échange avec l&#39;équipe grâce à son numéro, sans compte ; l&#39;équipe dispose d&#39;un état de traitement, d&#39;un export CSV et d&#39;un rôle <strong>Mainteneur</strong> dédié — lequel rédige et annote, mais ne publie pas : la mise en ligne reste au rôle Éditeur.</li><li><strong>Élément de feuille de route</strong> : ce qui est envisagé, en cours, livré ou abandonné, et la version qui l&#39;a livré.</li></ul><p>Chaque extension s&#39;installe ou se désinstalle par organisation depuis l&#39;écran <strong>Plugins</strong> du back-office (voir <a href="/teuthis-cms-distribution/documentation/notice/7-utilisation-du-back-office#77-extensions-plugins">§7.7</a>). Désinstaller retire l&#39;extension, jamais les contenus déjà créés grâce à elle.</p>',32)])])}const m=s(a,[["render",r]]);export{g as __pageData,m as default};
